class RecordingPhysics implements ObstacleBodyFactory {
  readonly bodies: RecordingBody[] = [];

  createBody(id: string, position: Vec3, colliders: readonly ObstacleColliderDescriptor[]): ObstacleBody {
    const body = new RecordingBody(id, position, colliders);
    this.bodies.push(body);
    return body;
  }
}

function at<T>(items: readonly T[], index: number): T {
  const value = items[index];
  if (value === undefined) throw new Error('expected an item at index ' + index);
  return value;
}

function meshes(obstacle: RotatingObstacle): THREE.Mesh[] {
  return obstacle.object3d.children.filter((child): child is THREE.Mesh => child instanceof THREE.Mesh);
}

function lastRotation(body: RecordingBody): Quat {
  return at(body.rotations, body.rotations.length - 1);
}

describe('rotating obstacles', () => {
  it('builds a bar mesh and a matching cuboid collider', () => {
    const scene = new THREE.Scene();
    const physics = new RecordingPhysics();
    const bar = new RotatingBar({
      id: 'bar-1',
      position: { x: 1, y: 0.7, z: 2 },
      length: 6,
      width: 0.4,
      depth: 0.25,
      speed: 1,
      scene,
      physics,
    });

    expect(scene.children).toContain(bar.object3d);
    expect(meshes(bar)).toHaveLength(1);
    expect(bar.reach).toBeCloseTo(3, 9);

    const body = at(physics.bodies, 0);
    expect(body.id).toBe('bar-1');
    expect(body.position).toEqual({ x: 1, y: 0.7, z: 2 });
    expect(body.colliders).toHaveLength(1);
    const collider = at(body.colliders, 0);
    expect(collider.halfExtents.x).toBeCloseTo(3, 12);
    expect(collider.halfExtents.y).toBeCloseTo(0.125, 12);
    expect(collider.halfExtents.z).toBeCloseTo(0.2, 12);
    expect(collider.restitution).toBeCloseTo(0.45, 12);
  });

  it('advances deterministically and wraps a full revolution', () => {
    const make = (): RotatingBar => new RotatingBar({ id: 'bar', position: ORIGIN, speed: 2, phase: 0.5 });
    const first = make();
    const second = make();
    for (let i = 0; i < 120; i += 1) {
      first.update(1 / 60);
      second.update(1 / 60);
    }

    expect(first.angle).toBe(second.angle);
    expect(first.elapsed).toBeCloseTo(2, 9);
    expect(first.angle).toBeCloseTo(normalizeAngle(0.5 + 4), 9);

    const spinner = new Spinner({ id: 'spin', position: ORIGIN, speed: TWO_PI });
    expect(spinner.update(1)).toBe(0);
    expect(spinner.update(0.25)).toBeCloseTo(Math.PI / 2, 12);
    expect(spinner.update(0)).toBeCloseTo(Math.PI / 2, 12);
    expect(spinner.update(Number.NaN)).toBeCloseTo(Math.PI / 2, 12);
  });

  it('drives the kinematic body and the three.js group from the same angle', () => {
    const physics = new RecordingPhysics();
    const spinner = new Spinner({ id: 'spin', position: { x: 0, y: 1, z: 0 }, speed: 1, physics });
    spinner.update(Math.PI / 2);

    const expected = quaternionFromAxisAngle({ x: 0, y: 1, z: 0 }, Math.PI / 2);
    const applied = lastRotation(at(physics.bodies, 0));
    expect(applied.x).toBeCloseTo(expected.x, 12);
    expect(applied.y).toBeCloseTo(expected.y, 12);
    expect(applied.z).toBeCloseTo(expected.z, 12);
    expect(applied.w).toBeCloseTo(expected.w, 12);
    expect(spinner.object3d.quaternion.y).toBeCloseTo(expected.y, 12);
    expect(spinner.object3d.quaternion.w).toBeCloseTo(expected.w, 12);
  });

  it('spaces windmill blades evenly around the hub', () => {
    const mill = new Windmill({
      id: 'orchard-mill',
      position: { x: 0, y: 1.2, z: 11 },
      axis: { x: 0, y: 0, z: 1 },
      bladeCount: 4,
      bladeLength: 2.5,
      bladeWidth: 0.8,
      bladeDepth: 0.3,
      hubRadius: 0.5,
      speed: 1.15,
    });

    const blades = meshes(mill).filter((mesh) => mesh.name.startsWith('blade-'));
    expect(blades).toHaveLength(4);
    expect(meshes(mill)).toHaveLength(5);
    expect(mill.reach).toBeCloseTo(3, 9);

    const angles = blades
      .map((blade) => {
        expect(blade.position.z).toBeCloseTo(0, 9);
        expect(Math.hypot(blade.position.x, blade.position.y)).toBeCloseTo(1.75, 9);
        return normalizeAngle(Math.atan2(blade.position.y, blade.position.x));
      })
      .sort((a, b) => a - b);
    expect(at(angles, 0)).toBeCloseTo(0, 9);
    expect(at(angles, 1)).toBeCloseTo(Math.PI / 2, 9);
    expect(at(angles, 2)).toBeCloseTo(Math.PI, 9);
    expect(at(angles, 3)).toBeCloseTo(Math.PI * 1.5, 9);
  });

  it('freezes and hides disabled obstacles, then resumes them', () => {
    const physics = new RecordingPhysics();
    const bar = new RotatingBar({ id: 'gate-bar', position: ORIGIN, speed: 3, physics });
    bar.update(0.5);
    const parked = bar.angle;

    bar.setEnabled(false);
    expect(bar.object3d.visible).toBe(false);
    expect(at(physics.bodies, 0).enabledCalls.at(-1)).toBe(false);
    bar.update(1);
    expect(bar.angle).toBe(parked);

    bar.setEnabled(true);
    bar.update(0.5);
    expect(bar.angle).toBeGreaterThan(parked);
  });

  it('keeps continuity on speed changes and restores the configured phase on reset', () => {
    const spinner = new Spinner({ id: 'reactor', position: ORIGIN, speed: 2, phase: 0.4 });
    spinner.update(1);
    expect(spinner.angle).toBeCloseTo(2.4, 12);

    spinner.setSpeed(-1);
    expect(spinner.angle).toBeCloseTo(2.4, 12);
    spinner.update(1);
    expect(spinner.angle).toBeCloseTo(1.4, 9);

    spinner.reset();
    expect(spinner.elapsed).toBe(0);
    expect(spinner.speed).toBe(2);
    expect(spinner.angle).toBeCloseTo(0.4, 12);
  });

  it('releases scene, geometry and physics resources on dispose', () => {
    const scene = new THREE.Scene();
    const physics = new RecordingPhysics();
    const mill = new Windmill({ id: 'mill', position: ORIGIN, scene, physics });
    const parts = meshes(mill);
    let disposedGeometries = 0;
    for (const mesh of parts) {
      mesh.geometry.addEventListener('dispose', () => {
        disposedGeometries += 1;
      });
    }

    mill.dispose();
    expect(disposedGeometries).toBe(parts.length);
    expect(scene.children).not.toContain(mill.object3d);
    expect(at(physics.bodies, 0).disposed).toBe(true);
    expect(mill.disposed).toBe(true);
    const frozen = mill.angle;
    expect(mill.update(1)).toBe(frozen);
  });

  it('rejects malformed obstacle configuration', () => {
    expect(() => new RotatingBar({ id: '   ', position: ORIGIN })).toThrow(/id/);
    expect(() => new RotatingBar({ id: 'bar', position: ORIGIN, length: 0 })).toThrow(/length/);
    expect(() => new Spinner({ id: 'spin', position: ORIGIN, axis: ORIGIN })).toThrow(/axis/);
    expect(() => new Spinner({ id: 'spin', position: ORIGIN, speed: Number.POSITIVE_INFINITY })).toThrow(/speed/);
    expect(() => new Spinner({ id: 'spin', position: { x: 0, y: Number.NaN, z: 0 } })).toThrow(/position/);
    expect(() => new Windmill({ id: 'mill', position: ORIGIN, bladeCount: 1 })).toThrow(/blade count/i);
  });
});

